PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?book ?bookLabel WHERE {
  ?book rdfs:label "Assassin's Apprentice" @en .
  ?book rdfs:label ?bookLabel .
  FILTER(LANG(?bookLabel) = "en")
}

